def badge(text,kind=''):
    return f'<span class="badge {kind}"><span class="dot" aria-hidden="true"></span>{text}</span>'
def btn(text,icon='plus',href=None,kind='',attrs=''):
    tag='a' if href else 'button'
    return f'<{tag} {"href="+chr(34)+href+chr(34) if href else "type=\"button\""} class="btn {kind}" {attrs}>{ic(icon)}<span>{text}</span></{tag}>'
def link(text,href):return f'<a class="text-link" href="{href}">{text}{ic("left")}</a>'
def section(title,action='',sub=''):return f'<div class="section-head"><h2>{title}</h2>{action or (f"<small>{sub}</small>" if sub else "")}</div>'
def metric(title,value,sub,icon,emphasis=''):
    return f'<div class="metric {emphasis}"><div class="metric-top"><span>{title}</span>{ic(icon)}</div><strong><bdi>{value}</bdi></strong><small>{sub}</small></div>'
def metrics(rows,money=False):return '<div class="metrics '+('money-metrics' if money else '')+'">'+''.join(metric(*x) for x in rows)+'</div>'
def notice(title,text,kind='',action=''):
    return f'<aside class="notice {kind}">{ic("warning" if kind in ("warn","") else "info" if kind=="info" else "success" if kind=="positive" else "error")}<div class="grow"><h3>{title}</h3><p>{text}</p></div>{action}</aside>'
def head(title,desc,action='',eyebrow='סביבת העבודה / הדגמה מקומית'):
    return f'<div class="page-head"><div><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="subtitle">{desc}</p></div><div class="actions">{action}</div></div>'
def task(title,sub,status='היום',kind='',done=False):
    return f'<div class="task"><button type="button" class="check" data-check aria-pressed="{str(done).lower()}" aria-label="סימון משימה: {title}"><span>{ic("check")}</span></button><div class="grow"><h3>{title}</h3><p>{sub}</p></div>{badge(status,kind)}</div>'
def empty(kind,title,text,action='',hidden=False):
    return f'<div class="empty-state empty-inline" {"hidden" if hidden else ""} data-empty><img src="assets/empty/{kind}.svg" alt="" width="180" height="128"><h3>{title}</h3><p>{text}</p>{action}</div>'
def field(id,label,value='',hint='',type='text',required=False,attrs=''):
    return f'<div class="field"><label for="{id}">{label}{" <span class=\"muted\">(חובה)</span>" if required else ""}</label><input id="{id}" name="{id}" type="{type}" value="{esc(value)}" {"required" if required else ""} {attrs} {"aria-describedby=\""+id+"-hint\"" if hint else ""}>{f"<small id=\"{id}-hint\">{hint}</small>" if hint else ""}</div>'
def toolbar(placeholder,filters,kind=''):
    f='<div class="toolbar"><label class="search-field">'+ic('search')+f'<span class="sr-only">{placeholder}</span><input type="search" data-search placeholder="{placeholder}" autocomplete="off"></label>'
    if kind:f+=f'<label class="sr-only" for="kind-filter">סוג</label><select id="kind-filter" class="select" data-kind><option value="all">כל הסוגים</option>{kind}</select>'
    f+='</div><div class="filters" aria-label="סינון לפי מצב" data-filters>'
    f+=''.join(f'<button type="button" class="filter" data-filter="{key}" aria-pressed="{str(i==0).lower()}">{label}<span class="count">{count}</span></button>' for i,(key,label,count) in enumerate(filters))
    return f+'</div><div class="results-meta"><span data-result-count aria-live="polite" aria-atomic="true"></span><span>כל הרשומות בדויות</span></div>'
def table(headers,rows,caption='',attrs=''):
    out=f'<div class="data-table-wrap" {attrs}><table class="data-table" role="table">'+(f'<caption>{caption}</caption>' if caption else '')+'<thead role="rowgroup"><tr role="row">'+''.join(f'<th scope="col" role="columnheader">{h}</th>' for h in headers)+'</tr></thead><tbody role="rowgroup">'
    for row in rows:
        values,options=row if isinstance(row,tuple) else (row,{})
        rowattr=' '.join(f'data-{key}="{esc(str(val))}"' for key,val in options.items())
        out+=f'<tr role="row" {rowattr}>'+''.join(f'<td role="cell" data-label="{headers[i]}" {"class=\"amount\"" if "<bdi>₪" in v or v.startswith("<bdi>−₪") else ""}><span class="mobile-cell-label" aria-hidden="true">{headers[i]}</span>{v}</td>' for i,v in enumerate(values))+'</tr>'
    return out+'</tbody></table></div>'
def maincell(title,sub,icon):return f'<div class="table-main"><span class="table-icon">{ic(icon)}</span><div><strong>{title}</strong><small>{sub}</small></div></div>'
def detailsbtn(type,id,text='פתיחה'):return btn(text,'left',attrs=f'data-detail="{type}" data-record="{id}"')
def event_compact(day,title,client,kind='בהפקה',warn=False):
    return f'<a href="event.html" class="card event-compact"><span class="date-tile"><strong>{day}</strong><small>נובמבר</small></span><div class="grow"><h3>{title}</h3><p>{client} · 80 משתתפים</p><div class="row gap8 wrap">{badge(kind)}{badge("2 קצוות פתוחים","warn") if warn else ""}</div></div>{ic("left")}</a>'
def facts(items):
    items=[(k,('<bdi>'+v+'</bdi>') if v and v[0].isdigit() else v) for k,v in items]
    return '<dl class="mini-facts">'+''.join(f'<div><dt>{k}</dt><dd>{v}</dd></div>' for k,v in items)+'</dl>'

